diagram.source:
digraph release {
  rankdir=LR
  node [shape=box, style=rounded]
  subgraph cluster_ci {
    label="Continuous integration"
    Commit -> Build -> Test
  }
  Review [shape=diamond, label="Approved?"]
  Test -> Review [label="passes"]
  Test -> Build [label="fails", style=dashed]
  Review -> Release [label="yes"]
  Release [shape=ellipse]
}
